```python
class Car:
    def __init__(self, brand):
        self.brand = brand
    def drive(self):
        print(f"{self.brand} is driving")

car1 = Car('Toyota')
car1.drive()
```

```python
class Account:
    def __init__(self, balance):
        self.__balance = balance  # private attribute

    def get_balance(self):
        return self.__balance

acc = Account(1000)
print(acc.get_balance())
```

```python
class Animal:
    def sound(self):
        print('Animal sound')

class Cat(Animal):
    def sound(self):
        print('Meow')

cat = Cat()
cat.sound()  # Meow
```

```python
class Parent:
    def greet(self):
        print('Hello from Parent')

class Child(Parent):
    def greet(self):
        print('Hello from Child')

c = Child()
c.greet()  # Hello from Child
```

```python
def make_sound(animal):
    animal.sound()

class Dog:
    def sound(self):
        print('Bark')

class Cat:
    def sound(self):
        print('Meow')

make_sound(Dog())  # Bark
make_sound(Cat())  # Meow
```

```python
class Parent:
    def __init__(self):
        print('Parent init')

class Child(Parent):
    def __init__(self):
        super().__init__()
        print('Child init')

c = Child()
```

```python
class Book:
    def __init__(self, title):
        self.title = title

    def __str__(self):
        return f"Book title: {self.title}"

b = Book('Python 101')
print(b)  # Book title: Python 101
```
